"""Summarize the completed raw/JPEG FFCV comparisons."""
import argparse
import csv
import json
from pathlib import Path
import re
import shutil
import statistics

ROOT = Path(__file__).resolve().parents[4]
OUT = ROOT/'results/ffcv_jpeg_20261005'


def write_csv(path, rows):
    with path.open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def write_table(rows):
    lines = [
        '% Generated by fastlens/benchmarks/development/reports/report_compressed_ffcv.py.',
        r'\begin{table}[t]',
        r'\centering',
        r'\caption{FFCV raw-RGB and JPEG throughput (images/s), using the same RGB model within each row. Values are medians of three warm-cache trials: 65,536 images per training window and all 50,000 validation images for inference.}',
        r'\label{tab:ffcv-compression}',
        r'\fontsize{8}{9}\selectfont\setlength{\tabcolsep}{3pt}',
        r'\begin{tabular}{@{}lrrrr@{}}',
        r'\toprule',
        r'& \multicolumn{2}{c}{Training} & \multicolumn{2}{c}{Inference} \\',
        r'RGB model & Raw & JPEG & Raw & JPEG \\',
    ]
    for gpu in ('RTX 4090', 'H100'):
        selected = [r for r in rows if r['gpu'] == gpu]
        if not selected:
            continue
        lines += [r'\midrule', r'\multicolumn{5}{@{}l}{\textit{' + gpu + r'}} \\']
        for model in dict.fromkeys(r['model'] for r in selected):
            values = []
            for task in ('training', 'inference'):
                matching = [r for r in selected if r['model'] == model and r['task'] == task]
                values += ([f"{matching[0][field]:,.0f}" for field in
                            ('raw_images_per_s', 'jpeg_images_per_s')] if matching else ['--', '--'])
            label = model.removesuffix(' RGB').removesuffix(' reference')
            lines.append(label + ' & ' + ' & '.join(values) + r' \\')
    lines += [r'\bottomrule', r'\end{tabular}', r'\end{table}']
    (ROOT/'fastlens/docs/paper/sections/07_ffcv_compression_table.tex').write_text('\n'.join(lines)+'\n')


def update_main_training(rows):
    """Use the completed raw cohort consistently in both paper training tables."""
    primary = ROOT/'results/paper/training_windows.csv'
    with primary.open() as stream:
        summaries = list(csv.DictReader(stream))
    selected_path = ROOT/'results/paper/evaluation_records/training_window_selected.csv'
    with selected_path.open() as stream:
        selected = list(csv.DictReader(stream))
    refreshed = {}
    for pair in [r for r in rows if r['task'] == 'training']:
        model = pair['model'].removesuffix(' RGB')
        old, = [r for r in summaries if (r['gpu'], r['model'], r['pipeline']) ==
                (pair['gpu'], model, 'FFCV')]
        reference = json.loads((ROOT/old['raw_results'].split(';')[0]).read_text())
        paths = pair['raw_results'].split(';')
        trials = [json.loads((ROOT/path).read_text()) for path in paths]
        for trial in trials:
            for key in ('initial_model_hash', 'sample_order_sha256', 'precision', 'images',
                        'updates', 'warmup_updates', 'batch', 'accumulation', 'seed',
                        'augmentation_configuration', 'compile', 'tf32', 'cpu_affinity',
                        'pytorch_workers', 'host_threads'):
                assert trial[key] == reference[key], (model, pair['gpu'], key)
        rates = [t['images']/t['seconds'] for t in trials]
        assert len(rates) == 3
        coefficient = statistics.stdev(rates)/statistics.mean(rates)
        old.update(median_images_per_s=statistics.median(rates), min_images_per_s=min(rates),
                   max_images_per_s=max(rates), median_elapsed_s=statistics.median(t['seconds'] for t in trials),
                   raw_results=pair['raw_results'], cv_percent=100*coefficient,
                   coefficient_of_variation=coefficient,
                   implementation_cohort='ffcv_raw_encoding_control_20261005',
                   notes='Three-trial raw-RGB encoding-control cohort; matched training contract with historical primary FFCV. Historical observations retained; no causal attribution of timing changes to code.')
        refreshed[pair['gpu'], model] = old
    assert len(refreshed) == 10
    for row in selected:
        if row['pipeline'] != 'FFCV':
            continue
        workload = row['paper_workload']
        model = ('MobileNetV2' if workload.startswith('MobileNetV2') else
                 'EfficientNet-B0 reference' if workload.startswith('eFUN') else
                 workload.removesuffix(' DCT'))
        source = refreshed[row['gpu'], model]
        row.update(median_images_per_s=source['median_images_per_s'])
    systems = ['PyTorch', 'DALI', 'CoorDL', 'FFCV', 'FastLens']
    rates = {(r['gpu'], r['paper_workload'], r['pipeline']): float(r['median_images_per_s'])
             for r in selected}
    workloads = list(dict.fromkeys((r['gpu'], r['paper_workload']) for r in selected))
    wins = sum(rates[g, m, 'FastLens'] > rates[g, m, 'FFCV'] for g, m in workloads)
    gains = [statistics.mean(100*(rates[g, m, 'FastLens']/rates[g, m, system]-1)
                             for g, m in workloads) for system in systems[:-1]]
    paper = ROOT/'fastlens/docs/paper/sections/07_evaluation.tex'
    text = paper.read_text()
    label = r'\label{tab:training-window}'
    prefix, remainder = text.split(label, 1)
    block, suffix = remainder.split(r'\end{tabular}', 1)
    output, gpu, count = [], None, 0
    for line in block.splitlines(keepends=True):
        match = re.search(r'\\multirow\{\d+\}\{\*\}\{(RTX 4090|H100)\}', line)
        if match:
            gpu = match.group(1)
        cells = line.split('&')
        if len(cells) == 7 and cells[0].strip() != 'GPU':
            model = cells[1].strip()
            values = [rates[gpu, model, system] for system in systems]
            shown = [rf'\textbf{{{v:,.0f}}}' if v == max(values) else f'{v:,.0f}' for v in values]
            line = ' & ' + model + ' & ' + ' & '.join(shown) + r' \\' + '\n'
            count += 1
        output.append(line)
    assert count == len(workloads) == 10
    text = prefix + label + ''.join(output) + r'\end{tabular}' + suffix
    paragraph = (rf'For the 10 configurations in Table~\ref{{tab:training-window}}, \sys{{}} achieves higher median throughput than raw-RGB FFCV in {wins} configurations. '
                 'Averaged across these configurations, the deployment throughput differences relative to PyTorch, DALI, CoorDL, and FFCV are '
                 + ', '.join(f'{v:.1f}\\%' for v in gains[:-1]) + f', and {gains[-1]:.1f}\\%, respectively. '
                 'These deployment results include differences between the RGB and DCT models; they do not isolate input-pipeline efficiency.')
    text, replacements = re.subn(r'For the 10 configurations in Table~\\ref\{tab:training-window\}[^\n]*',
                                 lambda _: paragraph, text)
    assert replacements == 1
    backup = OUT/'training_windows_before_raw_refresh.csv'
    if not backup.exists():
        shutil.copyfile(primary, backup)
    write_csv(primary, summaries)
    paper.write_text(text)


def update_manifest(rows):
    path = ROOT/'results/experiment_manifest.csv'
    with path.open() as stream:
        reader = csv.DictReader(stream)
        fields, previous = reader.fieldnames, list(reader)
    prefix = 'ffcv_encoding_20261005:'
    entries = {row['experiment_id']: row for row in previous}
    for pair in rows:
        for encoding in ('raw', 'jpeg'):
            paths = pair[encoding + '_results'].split(';')
            result = json.loads((ROOT/paths[0]).read_text())
            if pair['task'] == 'inference':
                config = json.loads(Path(result['contract']).read_text())['execution']
                checkpoint = result['model']['checkpoint']
                batch, precision = config['batch_size'], config['precision']
            else:
                checkpoint = 'initialization_sha256:' + result['initial_model_hash']
                batch, precision = result['batch'], result['precision']
            row = dict.fromkeys(fields, '')
            row.update(experiment_id=prefix+':'.join((pair['gpu'], pair['model'], pair['task'], encoding)),
                       phase='FFCV-encoding', task=pair['task'], gpu=pair['gpu'],
                       architecture=pair['model'].removesuffix(' RGB').removesuffix(' reference'),
                       rgb_model=pair['model'], model_variant=pair['model'], domain='RGB', pipeline='FFCV',
                       checkpoint=checkpoint, sample_count=pair['samples'], precision=precision, batch_size=batch,
                       status='DONE', result_file=';'.join(paths), correctness='PASS',
                       notes=f'Three-trial {encoding} Beton encoding control; trial ranges retained in results/ffcv_jpeg_20261005/comparison.csv. No cross-domain system-speedup claim.')
            entries[row['experiment_id']] = row
    write_csv(path, list(entries.values()))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--partial', action='store_true',
                        help='Report completed pairs while occupied GPUs delay the remaining runs')
    args = parser.parse_args()
    def summaries(task, gpu):
        path = OUT/task/gpu/'summary.json'
        if args.partial and not path.exists():
            return []
        return json.loads(path.read_text())

    comparisons = []
    for gpu in ('4090', 'H100'):
        inference_raw = summaries('inference_raw', gpu)
        inference_jpeg = summaries('inference', gpu)
        training_jpeg = summaries('training', gpu)
        training_raw = summaries('training_raw', gpu)
        if not args.partial:
            assert len(inference_raw) == len(inference_jpeg) == len(training_jpeg) == len(training_raw) == 5
        for jpeg in inference_jpeg + training_jpeg:
            model, task = jpeg['model'], jpeg['task']
            assert jpeg['trials'] == 3
            matches = [r for r in (inference_raw if task == 'inference' else training_raw)
                       if r['model'] == model]
            if args.partial and not matches:
                continue
            raw, = matches
            assert raw['trials'] == 3
            raw_paths = raw['raw_results']
            if task == 'inference':
                raw_top1, jpeg_top1 = raw['top1'], jpeg['top1']
            else:
                raw_top1 = jpeg_top1 = None
                # The JPEG training arm preserves the existing RGB window contract.
                reference = json.loads((ROOT/raw_paths[0]).read_text())
                for path in jpeg['raw_results']:
                    measured = json.loads((ROOT/path).read_text())
                    for key in ('initial_model_hash', 'sample_order_sha256', 'precision',
                                'images', 'updates', 'warmup_updates', 'batch', 'accumulation'):
                        assert measured[key] == reference[key], (model, key)
            raw_rate = float(raw['median_images_per_s'])
            comparisons.append(dict(gpu=jpeg['gpu'], model=model, task=task,
                                    samples=jpeg['samples'], raw_images_per_s=raw_rate,
                                    jpeg_images_per_s=jpeg['median_images_per_s'],
                                    jpeg_over_raw=jpeg['median_images_per_s']/raw_rate,
                                    raw_min_images_per_s=raw['min_images_per_s'],
                                    raw_max_images_per_s=raw['max_images_per_s'],
                                    jpeg_min_images_per_s=jpeg['min_images_per_s'],
                                    jpeg_max_images_per_s=jpeg['max_images_per_s'],
                                    raw_top1=raw_top1, jpeg_top1=jpeg_top1,
                                    raw_results=';'.join(raw_paths), jpeg_results=';'.join(jpeg['raw_results']),
                                    reference_scope='Remeasured with corrected FFCV consumer stream' if task == 'inference'
                                    else 'Remeasured raw RGB reference; matched initialization and sample order'))
    write_csv(OUT/'comparison.csv', comparisons)
    write_table(comparisons)
    if not args.partial:
        update_main_training(comparisons)
        update_manifest(comparisons)
    storage = []
    for split, raw_path in [('train', ROOT/'results/preparation/p0_ffcv/train_window.beton'),
                            ('val', Path('/home/tangyuxin/tmp/dct-major-coordl-full-20260924/ffcv.beton')),
                            ('train_full', Path('/mnt/nvme2/home/tangyuxin/fastlens_ffcv_full_train_20261002/train_window.beton'))]:
        record = json.loads((OUT/'preparation'/split/'conversion.json').read_text())
        raw_size = raw_path.stat().st_size
        storage.append(dict(split=split, samples=record['samples'], raw_beton_bytes=raw_size,
                            jpeg_beton_bytes=record['representation_bytes'], source_jpeg_bytes=record['jpeg_bytes'],
                            reduction_percent=100*(1-record['representation_bytes']/raw_size),
                            scope=f"{record['samples']} images; Beton metadata and padding included; external sample manifests excluded"))
    write_csv(OUT/'storage.csv', storage)
    print(f'Wrote {len(comparisons)}/20 throughput comparisons and {len(storage)} storage comparisons.')


if __name__ == '__main__':
    main()
